# Useful global metadata settings,
#  enabled all WxS requests, sets common projections,
#  and defaults to JSON for default wms_feature_info
#

# 'ows_enable_request' '*'
# 'ows_srs' 'EPSG:32614 EPSG:4326 EPSG:3857'
# #'wms_srs' 'EPSG:32614 EPSG:4326 EPSG:3857'
# 'wms_feature_info_mime_type' 'application/json'
# "wms_allow_getmap_without_styles" "true"
# 'wfs_enable_request' '*'
# 'wms_getfeatureinfo_formatlist' 'geojson'

# 
# GLOBAL
'ows_enable_request'  'GetMap GetFeature GetFeatureInfo GetCapabilities GetLegendGraphic'
"gml_featureid" "gid"
#WFS
'wfs_srs' 'EPSG:32614 EPSG:4326'
'wfs_getfeature_formatlist' 'gml,geojson'
# WMS
'wms_srs' 'EPSG:32614 EPSG:4326 EPSG:3857'
"wms_allow_getmap_without_styles" "true"









